// === BOOLEAN ALGEBRA & GATES ===
bool AND(bool A, bool B) { return A & B; }
bool OR(bool A, bool B) { return A | B; }
bool NOT(bool A) { return !A; }
bool XOR(bool A, bool B) { return A ^ B; }

// De Morgan's Laws (NAND/NOR equivalence)
// !(A & B) == (!A | !B)
// !(A | B) == (!A & !B)

// Identity: A | 0 = A, A & 1 = A
// Absorption: A | 1 = 1, A & 0 = 0
// Idempotence: A | A = A, A & A = A
// Complements: A | !A = 1, A & !A = 0
// Involution: !!A = A

// === BITWISE OPERATIONS (C/C++/Rust) ===
unsigned int flags = 0b1010;
unsigned int MASK_A = 0b0001;
unsigned int MASK_B = 0b0010;
unsigned int SET = 0x01;  // Bit 0

// Set bit
flags |= SET;       // 1010 | 0001 = 1011

// Clear bit
flags &= ~SET;      // 1011 & ~0001 = 1010

// Toggle bit
flags ^= SET;       // 1010 ^ 0001 = 1011

// Check if bit is set
bool is_set = (flags & MASK_B) != 0; // Check bit 1 (0010)

// Shift Operations
int a = 8;        // 0b1000
int lshift = a << 2; // 32 (0b100000) (Multiply by 4)
int rshift = a >> 1; // 4 (0b0100) (Divide by 2, floor)

// Arithmetic vs Logical Shift (Signed vs Unsigned)
unsigned int u = 0b10000000 >> 1; // 0x40 (Logical, inserts 0)
int s = -8;
int s_arith = s >> 1; // -4 (Arith, preserves sign bit)

// Swapping without temp variable
int x = 5, y = 10;
x ^= y;
y ^= x;
x ^= y; // x=10, y=5

// Bit Isolation (Power of 2 check)
bool is_pow2(int n) { return (n > 0) && ((n & (n - 1)) == 0); }

// Extract LSB (Rightmost set bit)
int lsb = n & -n;

// Clearing LSB (Turn off rightmost set bit)
n = n & (n - 1);
